       n++;
       for(k in old[out]) if((r.need[k]|0)!==old[out][k]*2) bad.push(r.name+' needs '+(r.need[k]|0)+' '+k+', not '+(old[out][k]*2)+' (twice the old '+old[out][k]+')');
