       if((r.need.scrap|0)!==3||(r.need.wire|0)!==2) bad.push('the Component Kit recipe moved ('+JSON.stringify(r.need)+')');
     } else if(out==='medkit'){
       if((r.need.bandage|0)!==2||(r.need.comp|0)!==1) bad.push('the Medkit recipe moved ('+JSON.stringify(r.need)+')');
     }
   }
   if(n!==4) bad.push('the bench holds '+n+' gun recipes, not four');
   return bad.length?bad.join('; '):null; }},
